import sys

MOD = 1_000_000_007

x, n = map(int, sys.stdin.buffer.readline().split())
primes = []

if x % 2 == 0:
    primes.append(2)
    while x % 2 == 0:
        x //= 2

p = 3
while p * p <= x:
    if x % p == 0:
        primes.append(p)
        while x % p == 0:
            x //= p
    p += 2

if x > 1:
    primes.append(x)

answer = 1

for p in primes:
    exponent = 0
    power = p
    while power <= n:
        exponent += n // power
        if power > n // p:
            break
        power *= p
    answer = answer * pow(p, exponent, MOD) % MOD

print(answer)
